// SYNTHETIC extension of status/fixture.json with the run report, the subruns and the stats view
// of the report contract (/root/night/REPORT_CONTRACT.md, schema 1, with the host-session addendum
// of 2026-11-07). The committed fixture is generated by the Worker's own handler and does not carry
// these fields yet; until it does, the DOM tests build the pages against this function's output.
// Nothing here is measured: every value is invented to exercise the markup, and the file is used by
// tests and by screenshot scripts only, never shipped.
const LOGS = 'https://logs.kayfabe.dev';
const HEX = (n, seed) => {
  let x = 0;
  for (const c of seed) x = (x * 31 + c.charCodeAt(0)) >>> 0;
  let out = '';
  for (let i = 0; i < n; i++) {
    x = (x * 1103515245 + 12345) >>> 0;
    out += (x >>> 16 & 15).toString(16);
  }
  return out;
};

function subrunsFor(run) {
  const subs = [
    {
      sub: 'host',
      kind: 'host_bare',
      os: 'host',
      guest_driver: null,
      host_driver: '580.159.04',
      stages: ['cuda_host', 'merge_bar'],
    },
  ];
  if (run.platform === 'linux' || run.platform === 'both')
    subs.push({
      sub: 'linux-580.159.03',
      kind: 'linux_guest',
      os: 'linux',
      guest_driver: '580.159.03',
      host_driver: '580.159.04',
      stages: ['thin_suite', 'cuda_guest'],
    });
  if (run.platform === 'windows' || run.platform === 'both')
    subs.push({
      sub: 'windows-580.88',
      kind: 'windows_guest',
      os: 'windows',
      guest_driver: '580.88',
      host_driver: '580.159.04',
      stages: ['windows_gate'],
    });
  return subs;
}

function reportFor(run, index) {
  const bad = run.verdict === 'FAIL';
  const subs = subrunsFor(run);
  const tests = [];
  const perf = [];
  const apps = [];
  let clock = Date.parse(run.started_at ?? '2026-10-04T08:00:00Z');
  for (const s of subs) {
    const names =
      s.kind === 'host_bare'
        ? ['merge_bar arm 1', 'merge_bar arm 2', 'merge_bar arm 3']
        : s.kind === 'linux_guest'
          ? ['concurrency', 'mmu_invalidate', 'pushbuffer_copy', 'sysmem_userd', 'ce_copy']
          : ['probe cup8', 'probe d3d11'];
    names.forEach((name, i) => {
      const result = bad && s.kind === 'linux_guest' && i === 0 ? 'FAIL' : i === names.length - 1 && index % 4 === 0 ? 'SKIP' : 'PASS';
      tests.push({ sub: s.sub, suite: s.kind === 'host_bare' ? 'raw_suite' : s.kind === 'linux_guest' ? 'thin_suite' : 'windows_gate', name, result, ms: 800 + 1700 * i });
    });
    if (s.kind !== 'windows_guest')
      perf.push(
        { sub: s.sub, name: s.kind === 'host_bare' ? 'cup8bench FP32 matmul (host)' : 'cup8bench FP32 matmul (guest)', value: s.kind === 'host_bare' ? 20.5 : 19.9, unit: 'TFLOPS', higher_is_better: true, suite: s.kind === 'host_bare' ? 'cuda_host' : 'cuda_guest', ref_value: s.kind === 'host_bare' ? null : 20.5, ref_ratio: s.kind === 'host_bare' ? null : 0.97 },
        { sub: s.sub, name: 'pushbuffer upload', value: 11.2, unit: 'GB/s', higher_is_better: true, suite: 'cuda_guest', ref_value: null, ref_ratio: null },
      );
    if (s.kind === 'windows_guest' && index % 2 === 1)
      apps.push(
        { sub: s.sub, name: 'Unigine Heaven', os: 'windows', result: 'PASS', note: '' },
        { sub: s.sub, name: 'Edge video', os: 'windows', result: 'FAIL', note: 'driver reset after 8 minutes' },
        { sub: s.sub, name: 'Blender', os: 'windows', result: 'NOT_RUN', note: 'not scheduled' },
      );
    s.verdict = bad && s.kind === 'linux_guest' ? 'FAIL' : run.verdict === 'PASS' ? 'PASS' : s.kind === 'windows_guest' && run.verdict !== 'FAIL' ? run.verdict : 'PASS';
    const pass = tests.filter((t) => t.sub === s.sub && t.result === 'PASS').length;
    const fail = tests.filter((t) => t.sub === s.sub && t.result === 'FAIL').length;
    const skip = tests.filter((t) => t.sub === s.sub && t.result === 'SKIP').length;
    s.counts = { pass, fail, skip };
    s.started_at = new Date(clock).toISOString().replace('.000', '');
    clock += 600000;
    s.ended_at = new Date(clock).toISOString().replace('.000', '');
    const start = subs.indexOf(s) * 50000 + index * 100;
    s.log_range = { start_byte: start, end_byte: start + 40960 };
  }
  // A subrun that was not run says so, with a reason.
  if (index % 5 === 0) {
    subs.push({ sub: 'windows-575.64.05', kind: 'windows_guest', os: 'windows', guest_driver: '575.64.05', host_driver: '580.159.04', verdict: 'NOT_RUN', reason: 'the small tier does not install a second Windows driver yet', stages: [], counts: { pass: 0, fail: 0, skip: 0 } });
  }
  const suites = [];
  for (const s of subs) {
    const names = [...new Set(tests.filter((t) => t.sub === s.sub).map((t) => t.suite))];
    for (const n of names) {
      const rows = tests.filter((t) => t.sub === s.sub && t.suite === n);
      suites.push({ sub: s.sub, name: n, pass: rows.filter((t) => t.result === 'PASS').length, fail: rows.filter((t) => t.result === 'FAIL').length, skip: rows.filter((t) => t.result === 'SKIP').length });
    }
  }
  const bytes = 120000 + index * 4096;
  return {
    schema: 1,
    run_id: run.id,
    commit: run.commit,
    tier: run.tier,
    die: run.die,
    family: run.family,
    gpu_name: 'synthetic ' + run.die,
    host_driver: '580.159.04',
    cpu_vendor: index % 2 ? 'amd' : 'intel',
    verdict: run.verdict,
    stages: run.stages,
    subruns: subs,
    suites,
    tests,
    apps,
    perf,
    windows: run.platform === 'linux' ? undefined : { gate: run.verdict === 'FAIL' ? 'FAIL' : 'PASS', install_s: 1260, probes: ['cup8', 'd3d11'], resets: bad ? 1 : 0, live_dumps_193: 0 },
    log: { url: LOGS + '/' + run.id + '/log.txt', bytes, sha256: HEX(64, run.id) },
  };
}

export function withReports(base) {
  const responses = structuredClone(base);
  const rows = [];
  let index = 0;
  for (const [key, value] of Object.entries(responses)) {
    if (!/^\/v1\/ci\/runs\/[a-z0-9-]+$/.test(key) || !value.run) continue;
    const run = value.run;
    index++;
    if (run.state === 'running') continue;
    run.report = reportFor(run, index);
    run.subruns = run.report.subruns;
    run.log = run.report.log;
    rows.push(run);
  }
  responses['/v1/ci/stats'] = {
    api: 'v1',
    stats: rows.map((run) => ({
      die: run.die,
      family: run.family,
      tier: run.tier,
      host_driver: run.report.host_driver,
      run_id: run.id,
      commit: run.commit,
      ended_at: run.ended_at,
      verdict: run.verdict,
      pass: run.report.tests.filter((t) => t.result === 'PASS').length,
      fail: run.report.tests.filter((t) => t.result === 'FAIL').length,
      skip: run.report.tests.filter((t) => t.result === 'SKIP').length,
      perf: run.report.perf,
    })),
  };
  return responses;
}

// One ranked answer of /v1/ci/subruns, for a die and OS that no exact subrun covers.
export function nearestAnswer(runs) {
  const list = runs.slice(0, 3);
  return {
    api: 'v1',
    subruns: list.map((run, i) => ({
      run_id: run.id,
      sub: 'linux-580.159.03',
      kind: 'linux_guest',
      os: 'linux',
      die: run.die,
      family: run.family,
      guest_driver: '580.159.03',
      host_driver: '580.159.04',
      cpu_vendor: i % 2 ? 'amd' : 'intel',
      commit: run.commit,
      ended_at: run.ended_at,
      verdict: 'PASS',
      counts: { pass: 5, fail: 0, skip: 0 },
      match: {
        exact: i === 0 ? ['os', 'host_driver'] : ['os'],
        relaxed:
          i === 0
            ? [
                { dim: 'commit', wanted: 'a1b2c3d4', found: run.commit.slice(0, 8) },
                { dim: 'cpu', wanted: 'amd', found: 'intel' },
              ]
            : [
                { dim: 'commit', wanted: 'a1b2c3d4', found: run.commit.slice(0, 8) },
                { dim: 'host_driver', wanted: '590.12.34', found: '580.159.04' },
                { dim: 'die_family', wanted: 'GA106', found: run.die },
              ],
      },
    })),
  };
}
